from lib import *
S = SS('s14')
steps = [
    step("输入处理器在每次 add_value 时就执行(add_value 一次 ' a '、一次 [' b ',' c '],各调用一次输入处理器,参数都是列表),collected 里已经是处理后的 ['a','b','c'];输出处理器要到 load_item 时才执行,每个字段一次(name 收到 ['a','b','c'],price 收到 ['9.9'])。两种处理器都不设(Identity)时,值总是列表:{'name': ['x', 'y']}。", t=tl(S(1)), mark=lidx(S(1), '输出', 'load_item 之后'), done=lidx(S(1), 'add_value 之后', '调用记录(add_value 阶段)'), kv=KV([['输入处理器', '每次 add_value 调用一次'], ['输出处理器', 'load_item 时每个字段一次'], ['Identity(默认)', '结果总是列表']], ['输出处理器'])),
    step("常用处理器:TakeFirst 取第一个“非 None 非空串”的值([None,'','a','b'] → 'a',全空返回 None,0 和 False 算有值:[0,False,5] → 0);Join 默认用空格拼接;MapCompose 逐个值依次套用函数,返回 None 的值被丢掉,函数返回列表则展平(['a,b','c'] 经 split → ['a','b','c']),函数出错时包装成 ValueError: Error in MapCompose with …;Compose 把整个列表交给函数,默认遇到 None 就停止,空列表 v[0] 抛 ValueError,stop_on_none=False 会把 None 继续传给下一个函数。", t=tl(S(2)), mark=lidx(S(2), 'TakeFirst()(0 和 False)', 'MapCompose(int)', 'Compose(lambda v: v[0])(空列表)'), done=lidx(S(2), 'TakeFirst()  ', 'Join(', 'MapCompose(str.strip)', 'split'), kv=KV([['TakeFirst', '第一个非 None 非空串(0 算有值)'], ['MapCompose', '逐值套函数,丢 None,展平列表'], ['Compose', '整个列表交给函数,默认遇 None 停'], ['出错', 'ValueError 包装']], ['TakeFirst'])),
    step("处理器从哪里来、谁优先:Loader 子类里的 name_in 压过 Item 字段元数据 input_processor(name 的输入是 loader:1,不是 meta:1);没有 name_in 的 tag 用字段元数据的输入处理器(meta:1)、输出用 default_output_processor(Join('+') → meta:1+meta:2);字段元数据里写了 output_processor 的 name 用它自己的 Join('|');什么都没写的 other 全用 default_*(default:1+default:2)。", t=tl(S(3)), mark=lidx(S(3), 'name  ', 'tag   ', 'other '), done=lidx(S(3), 'item ='), kv=KV([['输入:Loader 的 字段_in', '> Field 元数据 > default_input_processor'], ['输出:Loader 的 字段_out', '> Field 元数据 > default_output_processor'], ['name', 'loader:1|loader:2'], ['tag', 'meta:1+meta:2']], ['输入:Loader 的 字段_in'])),
    step("带选择器的 Loader:add_css('title','h1::text')、add_xpath、add_value 混用;price_in 里的处理器接收 loader_context 参数,拿到构造时传入的 rate=2,59.9 × 2 = 119.8;title 经 str.strip + TakeFirst 变成 'Python 入门';tags 用 Join(',') 得到 'a,b';没有声明输出处理器的 src 仍是列表。nested_css('#p') 之后在子 loader 里 add_css 的值写进同一个 item。loader.context 里有 item、rate、response、selector。", t=tl(S(4)), mark=lidx(S(4), 'loader_context', 'nested_css', 'loader.context'), kv=KV([['loader_context', '处理器多一个参数就能拿到构造参数(rate=2 → 119.8)'], ['nested_css', '子 loader 写同一个 item'], ['context 的键', 'item、rate、response、selector']], ['loader_context'])),
    step("空值:add_value(None) 什么都不收集([]);add_value('') 收集了 ['']、add_value([None, '']) 收集了 [None, '']、0 和 False 也照样收集;所以 load_item() 里没有 a、c(没收集到值就没有这个键),却有 b: ['']、d: [None, '']。replace_value 先清空再放新值(x: ['new']);add_value(re=…) 只取正则匹配到的部分(abc123 → ['123'])。", t=tl(S(5)), mark=lidx(S(5), 'load_item():'), done=lidx(S(5), 'add_value(None', 'replace_value'), kv=KV([['None / 空列表', '不收集,item 里没有这个键'], ["'' / [None, ''] / 0 / False", '照样收集'], ['replace_value', '清空旧值再放新值'], ['re=', '只取匹配部分']], ["'' / [None, ''] / 0 / False"])),
    step("scrapy.loader.ItemLoader 的默认 item 类是 scrapy.Item,没声明字段就往里放值会 KeyError:SL().add_value('title', 'x') 抛 KeyError 'title';声明了 title 的 item,放没声明的 other 同样 KeyError 'other',title 正常(得到 Declared 类型,值是 ['x']);子类里设 default_item_class = dict 就可以随便放字段。", t=tl(S(6)), mark=lidx(S(6), 'KeyError'), done=lidx(S(6), '声明了 title', 'default_item_class'), kv=KV([['默认 item 类', 'scrapy.Item(没声明的字段 KeyError)'], ['声明字段', '只能放声明过的'], ['default_item_class = dict', '随便放']], ['默认 item 类'])),
]
A = mkarts('s14', 14, 'Scrapy,ItemLoader,输入处理器,输出处理器,MapCompose,TakeFirst,真实验证,动画演示',
    '实测 ItemLoader:输入处理器每次 add_value 调用、输出处理器只在 load_item 时调用;TakeFirst 取第一个非 None 非空串(0 算有值)、MapCompose 丢 None 并展平列表;Loader 的 字段_in 压过 Field 元数据压过 default;loader_context 传参;None 不收集而 \'\' 会收集;默认 item 类是 scrapy.Item,未声明字段 KeyError。',
    'ItemLoader 把“提取”和“清洗”拆成输入处理器和输出处理器。它们什么时候被调用?TakeFirst、MapCompose 对 None、空串、0 各怎么处理?多处声明的处理器谁优先?这篇用真实的 itemloaders 逐项验证。',
    [('2 次 vs 1 次', 'name 字段 add_value 两次时,输入处理器调用 2 次,输出处理器只调用 1 次'), ('0', 'TakeFirst 对 [0, False, 5] 的返回值(0 算有值)'), ('KeyError', '往 scrapy.Item(没声明字段)的 ItemLoader 里放值的结果')],
    [('输入与输出', '<p>输入处理器在 <code>add_value</code> / <code>add_css</code> / <code>add_xpath</code> 时对每次提取到的值调用;输出处理器在 <code>load_item()</code> 时对每个字段已收集的全部值调用一次。默认都是 Identity,值是列表。</p>'),
     ('常用处理器', '<p><code>TakeFirst</code> 跳过 <code>None</code> 和空串;<code>MapCompose</code> 逐个值套函数并展平、丢掉 <code>None</code>;<code>Compose</code> 整体处理;<code>Join</code> 拼接字符串。出错会包装成 <code>ValueError</code>。</p>'),
     ('优先级', '<p>Loader 子类里的 <code>字段名_in/_out</code> 优先于 Item 字段元数据,再优先于 <code>default_input_processor / default_output_processor</code>。</p>'),
     ('选择器与上下文', '<p>构造 loader 时传 <code>response</code> 就能 <code>add_css</code>/<code>add_xpath</code>;处理器多声明一个 <code>loader_context</code> 参数就能拿到构造时传入的任意关键字参数。</p>'),
     ('空值', '<p><code>None</code> 和空列表不会被收集,所以对应字段不会出现在 item 里;空串、<code>0</code>、<code>False</code> 会被收集。</p>'),
     ('item 类', '<p><code>scrapy.loader.ItemLoader</code> 默认的 item 类是 <code>scrapy.Item</code>,没声明的字段会 <code>KeyError</code>;设 <code>default_item_class = dict</code> 则不限制字段。</p>')],
    steps,
    [ENV_Y + '(itemloaders 1.5.0、itemadapter 0.13.1)。实验直接在虚拟环境里构造 Loader、HtmlResponse,不经过网络',
     '没有验证:SelectJmes、MapCompose 配 w3lib 的 remove_tags 等其它常见处理器;add_jmes(JSON 响应);ItemLoader 与 dataclass / attrs item 的搭配;loader 用在 pipeline 之后(把已有 item 重新装载)的情形;处理器抛异常时的栈信息(只看了错误文本)'],
    'ItemLoader')
